#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Op {
    /// add text
    AddText(OpAddText),
    /// add note
    AddNote(OpAddNote),
    /// add math
    AddMath(OpAddMath),
    /// add shape
    AddShape(OpAddShape),
    /// add connector
    AddConnector(OpAddConnector),
    /// add image
    AddImage(OpAddImage),
    /// add frame
    AddFrame(OpAddFrame),
    /// add region
    AddRegion(OpAddRegion),
    /// add embed
    AddEmbed(OpAddEmbed),
    /// add extension
    AddExtension(OpAddExtension),
    /// patch
    Patch(OpPatch),
    /// remove
    Remove(OpRemove),
    /// arrange
    Arrange(OpArrange),
    /// focus
    Focus(OpFocus),
    /// define recipe
    DefineRecipe(OpDefineRecipe),
    /// define embed
    DefineEmbed(OpDefineEmbed),
}

impl Op {
    /// Picks the variant from its discriminating fields, then checks it.
    pub fn parse(value: &Value) -> Result<Self, UnionError> {
        let Some(o) = value.as_object() else {
            return Err(UnionError::NotAnObject);
        };
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("text")) {
            return serde_json::from_value(value.clone()).map(Op::AddText).map_err(|e| UnionError::Invalid { variant: "add text", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("note")) {
            return serde_json::from_value(value.clone()).map(Op::AddNote).map_err(|e| UnionError::Invalid { variant: "add note", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("math")) {
            return serde_json::from_value(value.clone()).map(Op::AddMath).map_err(|e| UnionError::Invalid { variant: "add math", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("shape")) {
            return serde_json::from_value(value.clone()).map(Op::AddShape).map_err(|e| UnionError::Invalid { variant: "add shape", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("connector")) {
            return serde_json::from_value(value.clone()).map(Op::AddConnector).map_err(|e| UnionError::Invalid { variant: "add connector", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("image")) {
            return serde_json::from_value(value.clone()).map(Op::AddImage).map_err(|e| UnionError::Invalid { variant: "add image", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("frame")) {
            return serde_json::from_value(value.clone()).map(Op::AddFrame).map_err(|e| UnionError::Invalid { variant: "add frame", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("region")) {
            return serde_json::from_value(value.clone()).map(Op::AddRegion).map_err(|e| UnionError::Invalid { variant: "add region", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type") == Some(&json!("embed")) {
            return serde_json::from_value(value.clone()).map(Op::AddEmbed).map_err(|e| UnionError::Invalid { variant: "add embed", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("add")) && o.get("type").and_then(Value::as_str).is_some_and(|s| !["text", "note", "math", "shape", "connector", "image", "frame", "region", "embed", "ink", "file"].contains(&s)) {
            return serde_json::from_value(value.clone()).map(Op::AddExtension).map_err(|e| UnionError::Invalid { variant: "add extension", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("define")) && o.get("kind") == Some(&json!("recipe")) {
            return serde_json::from_value(value.clone()).map(Op::DefineRecipe).map_err(|e| UnionError::Invalid { variant: "define recipe", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("define")) && o.get("kind") == Some(&json!("embed")) {
            return serde_json::from_value(value.clone()).map(Op::DefineEmbed).map_err(|e| UnionError::Invalid { variant: "define embed", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("patch")) {
            return serde_json::from_value(value.clone()).map(Op::Patch).map_err(|e| UnionError::Invalid { variant: "patch", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("remove")) {
            return serde_json::from_value(value.clone()).map(Op::Remove).map_err(|e| UnionError::Invalid { variant: "remove", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("arrange")) {
            return serde_json::from_value(value.clone()).map(Op::Arrange).map_err(|e| UnionError::Invalid { variant: "arrange", error: e.to_string() });
        }
        if o.get("op") == Some(&json!("focus")) {
            return serde_json::from_value(value.clone()).map(Op::Focus).map_err(|e| UnionError::Invalid { variant: "focus", error: e.to_string() });
        }
        Err(UnionError::NoVariant { options: "op: add, patch, remove, arrange, focus, define; type: text, note, math, shape, connector, image, frame, region, embed; kind: recipe, embed" })
    }
}

