/// One Element as read(detail: 'full') returns it and as the scene JSON every renderer draws from. Built-in types have typed, top-level fields; extension types put theirs in props. type is the discriminator. Coordinates are the reading Agent's.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum Element {
    /// text
    Text(ElementText),
    /// note
    Note(ElementNote),
    /// math
    Math(ElementMath),
    /// shape
    Shape(ElementShape),
    /// connector
    Connector(ElementConnector),
    /// image
    Image(ElementImage),
    /// frame
    Frame(ElementFrame),
    /// region
    Region(ElementRegion),
    /// embed
    Embed(ElementEmbed),
    /// ink
    Ink(ElementInk),
    /// file
    File(ElementFile),
    /// extension
    Extension(ElementExtension),
}

impl Element {
    /// Picks the variant from its discriminating fields, then checks it.
    pub fn parse(value: &Value) -> Result<Self, UnionError> {
        let Some(o) = value.as_object() else {
            return Err(UnionError::NotAnObject);
        };
        if o.get("type") == Some(&json!("text")) {
            return serde_json::from_value(value.clone()).map(Element::Text).map_err(|e| UnionError::Invalid { variant: "text", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("note")) {
            return serde_json::from_value(value.clone()).map(Element::Note).map_err(|e| UnionError::Invalid { variant: "note", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("math")) {
            return serde_json::from_value(value.clone()).map(Element::Math).map_err(|e| UnionError::Invalid { variant: "math", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("shape")) {
            return serde_json::from_value(value.clone()).map(Element::Shape).map_err(|e| UnionError::Invalid { variant: "shape", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("connector")) {
            return serde_json::from_value(value.clone()).map(Element::Connector).map_err(|e| UnionError::Invalid { variant: "connector", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("image")) {
            return serde_json::from_value(value.clone()).map(Element::Image).map_err(|e| UnionError::Invalid { variant: "image", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("frame")) {
            return serde_json::from_value(value.clone()).map(Element::Frame).map_err(|e| UnionError::Invalid { variant: "frame", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("region")) {
            return serde_json::from_value(value.clone()).map(Element::Region).map_err(|e| UnionError::Invalid { variant: "region", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("embed")) {
            return serde_json::from_value(value.clone()).map(Element::Embed).map_err(|e| UnionError::Invalid { variant: "embed", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("ink")) {
            return serde_json::from_value(value.clone()).map(Element::Ink).map_err(|e| UnionError::Invalid { variant: "ink", error: e.to_string() });
        }
        if o.get("type") == Some(&json!("file")) {
            return serde_json::from_value(value.clone()).map(Element::File).map_err(|e| UnionError::Invalid { variant: "file", error: e.to_string() });
        }
        if o.get("type").and_then(Value::as_str).is_some_and(|s| !["text", "note", "math", "shape", "connector", "image", "frame", "region", "embed", "ink", "file"].contains(&s)) {
            return serde_json::from_value(value.clone()).map(Element::Extension).map_err(|e| UnionError::Invalid { variant: "extension", error: e.to_string() });
        }
        Err(UnionError::NoVariant { options: "type: text, note, math, shape, connector, image, frame, region, embed, ink, file" })
    }
}

