/// A Send Bundle, or still_waiting when the timeout passed with nothing to deliver.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum WaitForUserOutput {
    /// Send Bundle
    SendBundle(SendBundle),
    /// still_waiting
    StillWaiting(WaitForUserOutputStillWaiting),
}

impl WaitForUserOutput {
    /// Picks the variant from its discriminating fields, then checks it.
    pub fn parse(value: &Value) -> Result<Self, UnionError> {
        let Some(o) = value.as_object() else {
            return Err(UnionError::NotAnObject);
        };
        if o.get("status") == Some(&json!("still_waiting")) {
            return serde_json::from_value(value.clone()).map(WaitForUserOutput::StillWaiting).map_err(|e| UnionError::Invalid { variant: "still_waiting", error: e.to_string() });
        }
        if true {
            return serde_json::from_value(value.clone()).map(WaitForUserOutput::SendBundle).map_err(|e| UnionError::Invalid { variant: "Send Bundle", error: e.to_string() });
        }
        Err(UnionError::NoVariant { options: "status: still_waiting" })
    }
}

/// Each variant's title and the fields it accepts.
pub const WAIT_FOR_USER_OUTPUT_FIELDS: &[(&str, &[&str])] = &[
    ("Send Bundle", &["kind", "send", "space", "from", "trigger", "said", "marks", "changes", "scene", "elsewhere", "viewport", "selection", "region", "element", "payload", "user_still_writing", "images", "also_sent_to", "redelivered", "pending_after", "next"]),
    ("still_waiting", &["status", "pending_sends", "next"]),
];

impl<'de> Deserialize<'de> for WaitForUserOutput {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        let v = Value::deserialize(d)?;
        WaitForUserOutput::parse(&v).map_err(serde::de::Error::custom)
    }
}
